package io.github.kgcaudit.reader.pdf

/**
 * KS X 1001 의 한글 2,350자 — 우리말 글에 실제로 쓰이는 한글은 거의 모두 이 안에 있다. 되살린 글([BrokenHangul])이
 * 그럴듯한지 가리는 데 쓴다: 번호 체계가 다른 글꼴을 같은 규칙으로 풀면 "댦뗴꿹" 처럼 이 밖의 글자가 쏟아진다.
 *
 * 표는 가(U+AC00)부터 11,172자에 한 비트씩(파이썬 euc-kr 로 2바이트가 되는 글자). 플랫폼 문자 집합(EUC-KR)에 묻지
 * 않는 까닭: 안드로이드 · 자바마다 EUC-KR 이 확장 완성형(CP949)까지 받는지가 달라 결과가 기기마다 달라진다.
 */
internal object KsHangul {
    private val bits: ByteArray = java.util.Base64.getDecoder().decode(
        "",
    )

    fun contains(c: Char): Boolean {
        val i = c - '가'
        return i in 0 until 11172 && (bits[i / 8].toInt() shr (i % 8)) and 1 == 1
    }
}
